import{_ as n,o as s,c as o,a2 as a}from"./chunks/framework.CBVBgcDP.js";const h=JSON.parse('{"title":"Agent：跟着一次循环走完全程","description":"","frontmatter":{"title":"Agent：跟着一次循环走完全程","tags":["LLM","Agent","Function Calling","RAG","MCP","上下文工程"],"date":"2026-08-16"},"headers":[],"relativePath":"ai/agent/agent-loop.md","filePath":"ai/agent/agent-loop.md","lastUpdated":1786875695000}'),r={name:"ai/agent/agent-loop.md"};function e(l,t,d,g,i,p){return s(),o("div",null,[...t[0]||(t[0]=[a(`<h1 id="agent-跟着一次循环走完全程" tabindex="-1">Agent：跟着一次循环走完全程 <a class="header-anchor" href="#agent-跟着一次循环走完全程" aria-label="Permalink to &quot;Agent：跟着一次循环走完全程&quot;">​</a></h1><blockquote><p><strong>这份文档不按概念分类，按一次 agent 循环的执行顺序排列。</strong> Function Calling、RAG、MCP、上下文工程——它们不是四个并列的话题，是同一个循环里的四个位置。</p><p>每个条目固定三行：<strong>是什么</strong> / <strong>它往上下文里塞了多少 token</strong> / <strong>没有它会坏在哪</strong>。</p><p>第二行统一换成 token 预算，因为<strong>应用层的一切最后都是上下文预算问题</strong>。RAG 是往上下文塞检索结果，Function Calling 是塞 JSON schema，MCP 是塞工具发现的协议开销。谁塞得多、谁塞得值，就是这一层的全部工程。</p><p>🔗 前置：<a href="/blog/ai/llm-basics/glossary.html">LLM 基础：跟着一个 token 走完全程</a> · 思想原型：<a href="/blog/ai/agent/yao-2023-react.html">ReAct 论文笔记</a></p></blockquote><hr><h2 id="_0-骨架" tabindex="-1">0. 骨架 <a class="header-anchor" href="#_0-骨架" aria-label="Permalink to &quot;0. 骨架&quot;">​</a></h2><p><a href="/blog/ai/llm-basics/glossary.html#_0-骨架">glossary §0</a> 那 12 行讲的是<strong>一次前向传播</strong>。Agent 是在它外面再套一层循环：</p><div class="language-python line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki material-theme-palenight vp-code" tabindex="0"><code><span class="line"><span style="color:#BABED8;">ctx </span><span style="color:#89DDFF;">=</span><span style="color:#89DDFF;"> [</span><span style="color:#BABED8;">system_prompt</span><span style="color:#89DDFF;">,</span><span style="color:#BABED8;"> tool_schemas</span><span style="color:#89DDFF;">]</span><span style="color:#676E95;font-style:italic;">        # 还没开工就已经花掉的钱          §1</span></span>
<span class="line"><span style="color:#BABED8;">ctx </span><span style="color:#89DDFF;">+=</span><span style="color:#89DDFF;"> [</span><span style="color:#BABED8;">user_message</span><span style="color:#89DDFF;">]</span></span>
<span class="line"></span>
<span class="line"><span style="color:#89DDFF;font-style:italic;">while</span><span style="color:#89DDFF;"> True:</span></span>
<span class="line"><span style="color:#BABED8;">    resp </span><span style="color:#89DDFF;">=</span><span style="color:#82AAFF;"> llm</span><span style="color:#89DDFF;">(</span><span style="color:#82AAFF;">ctx</span><span style="color:#89DDFF;">)</span><span style="color:#676E95;font-style:italic;">                        # ← 整个 glossary 就是这一行     §0</span></span>
<span class="line"><span style="color:#BABED8;">    ctx </span><span style="color:#89DDFF;">+=</span><span style="color:#89DDFF;"> [</span><span style="color:#BABED8;">resp</span><span style="color:#89DDFF;">]</span><span style="color:#676E95;font-style:italic;">                          # 模型的输出立刻变成下一轮的输入</span></span>
<span class="line"></span>
<span class="line"><span style="color:#89DDFF;font-style:italic;">    if</span><span style="color:#BABED8;"> resp</span><span style="color:#89DDFF;">.</span><span style="color:#F07178;">tool_calls</span><span style="color:#89DDFF;">:</span><span style="color:#676E95;font-style:italic;">                    # 模型决定要调工具               §1</span></span>
<span class="line"><span style="color:#89DDFF;font-style:italic;">        for</span><span style="color:#BABED8;"> call </span><span style="color:#89DDFF;font-style:italic;">in</span><span style="color:#BABED8;"> resp</span><span style="color:#89DDFF;">.</span><span style="color:#F07178;">tool_calls</span><span style="color:#89DDFF;">:</span></span>
<span class="line"><span style="color:#BABED8;">            result </span><span style="color:#89DDFF;">=</span><span style="color:#82AAFF;"> execute</span><span style="color:#89DDFF;">(</span><span style="color:#82AAFF;">call</span><span style="color:#89DDFF;">)</span><span style="color:#676E95;font-style:italic;">         # 唯一真正接触外部世界的一行      §2</span></span>
<span class="line"><span style="color:#BABED8;">            ctx </span><span style="color:#89DDFF;">+=</span><span style="color:#89DDFF;"> [</span><span style="color:#BABED8;">result</span><span style="color:#89DDFF;">]</span><span style="color:#676E95;font-style:italic;">                # ★ 结果原样塞回上下文           §3</span></span>
<span class="line"><span style="color:#89DDFF;font-style:italic;">        continue</span><span style="color:#676E95;font-style:italic;">                           # 回到循环开头，带着更长的 ctx</span></span>
<span class="line"></span>
<span class="line"><span style="color:#89DDFF;font-style:italic;">    return</span><span style="color:#BABED8;"> resp                            </span><span style="color:#676E95;font-style:italic;"># 没有工具调用 = 结束</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br></div></div><p>三件事看完这段就该记住：</p><ol><li><strong><code>ctx</code> 只增不减</strong>。每一轮循环都在往同一个数组末尾追加，而这个数组是<a href="/blog/ai/llm-basics/glossary.html#上下文窗口-context-window">有长度上限</a>的。<strong>Agent 的全部工程难点，是管理这个只增不减的数组。</strong></li><li><strong><code>llm(ctx)</code> 里面是无状态的</strong>。模型不记得上一轮——它每次都是从头读完整个 <code>ctx</code>。所谓「记忆」完全是这个数组在承载。</li><li><strong><code>execute(call)</code> 是唯一的外部接口</strong>。RAG 是它的一种，搜索、读文件、跑代码都是它的一种。<strong>Agent 能力的上限 = 这一行能干什么。</strong></li></ol><h3 id="和-glossary-的对应关系" tabindex="-1">和 glossary 的对应关系 <a class="header-anchor" href="#和-glossary-的对应关系" aria-label="Permalink to &quot;和 glossary 的对应关系&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Agent 层</th><th>底层机制</th><th>在哪</th></tr></thead><tbody><tr><td><code>ctx</code> 只增不减</td><td>上下文窗口是训练决定的硬边界</td><td><a href="/blog/ai/llm-basics/glossary.html#上下文窗口-context-window">glossary §6</a></td></tr><tr><td>每轮重读整个 <code>ctx</code></td><td>Prefill 阶段，算力受限</td><td><a href="/blog/ai/llm-basics/glossary.html#prefill-vs-decode">glossary §6</a></td></tr><tr><td>长 ctx 变慢变贵</td><td>KV Cache 随长度线性膨胀</td><td><a href="/blog/ai/llm-basics/glossary.html#kv-cache">glossary §6</a></td></tr><tr><td>一步错，后面全歪</td><td>自回归误差自我放大</td><td><a href="/blog/ai/llm-basics/glossary.html#自回归生成-autoregressive-generation">glossary §6</a></td></tr><tr><td>模型「学会」了先想再做</td><td>RLVR 把 CoT 训进了权重</td><td><a href="/blog/ai/llm-basics/glossary.html#_4-推理训练-rlvr-rl-with-verifiable-rewards">glossary §7</a></td></tr></tbody></table><h3 id="速查表" tabindex="-1">速查表 <a class="header-anchor" href="#速查表" aria-label="Permalink to &quot;速查表&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名词</th><th>在哪</th><th>名词</th><th>在哪</th></tr></thead><tbody><tr><td>Function Calling / 工具定义</td><td><a href="#_1-开工前-工具定义的固定成本">§1</a></td><td>上下文工程</td><td><a href="#_3-上下文工程-管理那个只增不减的数组">§3</a></td></tr><tr><td>MCP</td><td><a href="#_1-开工前-工具定义的固定成本">§1</a></td><td>有效上下文 / context rot</td><td><a href="#_3-上下文工程-管理那个只增不减的数组">§3</a></td></tr><tr><td>工具搜索 / 延迟加载</td><td><a href="#_1-开工前-工具定义的固定成本">§1</a></td><td>提示缓存</td><td><a href="#_4-账单-一次-agent-任务多少钱">§4</a></td></tr><tr><td>RAG / 分块 / 嵌入</td><td><a href="#_2-循环体-工具调用与-rag">§2</a></td><td>成功快、失败慢</td><td><a href="#_4-账单-一次-agent-任务多少钱">§4</a></td></tr><tr><td>结构化输出 / 约束解码</td><td><a href="#_2-循环体-工具调用与-rag">§2</a></td><td>ReAct</td><td><a href="#_5-这一切的思想原型">§5</a></td></tr></tbody></table><hr><h2 id="_1-开工前-工具定义的固定成本" tabindex="-1">1. 开工前：工具定义的固定成本 <a class="header-anchor" href="#_1-开工前-工具定义的固定成本" aria-label="Permalink to &quot;1. 开工前：工具定义的固定成本&quot;">​</a></h2><blockquote><p><strong>这是最反直觉的一节。</strong> 大多数人以为 agent 的成本在「跑了多少轮」，实际上很大一块在「还没开始跑」。</p></blockquote><h3 id="function-calling-工具调用" tabindex="-1">Function Calling（工具调用） <a class="header-anchor" href="#function-calling-工具调用" aria-label="Permalink to &quot;Function Calling（工具调用）&quot;">​</a></h3><ul><li><strong>是什么</strong>：把可用工具的名字、描述、参数 JSON Schema 拼进上下文，模型输出一个结构化的调用意图，由你的代码去执行。<strong>模型本身不能执行任何东西</strong>——它只是生成了一段表示「我想调用 X(a=1)」的文本。</li><li><strong>它往上下文里塞了多少 token</strong>：分两笔。 <ul><li><strong>系统提示开销</strong>（只要 <code>tools</code> 非空就自动加上，还不含工具定义本身）：Claude Opus 5 是 <strong>286 token</strong>（<code>tool_choice</code> 为 <code>auto</code>）/ <strong>406 token</strong>（强制调用）；Opus 4.7 是 675 / 804；Sonnet 5 是 354 / 474。</li><li><strong>工具定义本身</strong>：这才是大头，见下。</li></ul></li><li><strong>没有它会坏在哪</strong>：模型只能吐文本，碰不到任何外部状态。它连当前时间都不知道。</li></ul><h3 id="工具定义的真实开销" tabindex="-1">工具定义的真实开销 <a class="header-anchor" href="#工具定义的真实开销" aria-label="Permalink to &quot;工具定义的真实开销&quot;">​</a></h3><p>Anthropic 自己公布的实测数据（第一方，最可信的一组）：</p><table tabindex="0"><thead><tr><th>服务</th><th>工具数</th><th><strong>token</strong></th></tr></thead><tbody><tr><td>GitHub</td><td>35</td><td>≈26,000</td></tr><tr><td>Slack</td><td>11</td><td>≈21,000</td></tr><tr><td>Sentry</td><td>5</td><td>≈3,000</td></tr><tr><td>Grafana</td><td>5</td><td>≈3,000</td></tr><tr><td>Splunk</td><td>2</td><td>≈2,000</td></tr><tr><td><strong>合计</strong></td><td><strong>58</strong></td><td><strong>≈55,000</strong></td></tr></tbody></table><p><strong>58 个工具，55,000 token，在用户敲下第一个字之前就已经花掉了。</strong> 200k 上下文的 27%。 换算一下平均值：Slack 约 <strong>1,909 token/工具</strong>，GitHub 约 743。Jira 一家单独就 <strong>≈17,000 token</strong>。</p><p>Anthropic 还给了一个更狠的自曝：「我们内部见过工具定义在优化前消耗 <strong>134,000 token</strong>。」</p><h3 id="⚠️-而且不止是贵——是会变笨" tabindex="-1">⚠️ 而且不止是贵——是会变笨 <a class="header-anchor" href="#⚠️-而且不止是贵——是会变笨" aria-label="Permalink to &quot;⚠️ 而且不止是贵——是会变笨&quot;">​</a></h3><p>同一份文档里的另一句话，比成本数字重要得多：</p><blockquote><p><strong>一旦可用工具超过 30~50 个，Claude 挑对工具的能力就开始退化。</strong></p></blockquote><p><strong>成本和能力是一起崩的，而且崩在同一个地方。</strong> 这不是「加工具会变贵，但值得」的权衡——过了那条线，你是花更多的钱买更差的效果。</p><h3 id="mcp-model-context-protocol" tabindex="-1">MCP（Model Context Protocol） <a class="header-anchor" href="#mcp-model-context-protocol" aria-label="Permalink to &quot;MCP（Model Context Protocol）&quot;">​</a></h3><ul><li><strong>是什么</strong>：Anthropic 在 <strong>2024 年 11 月 25 日</strong>发布的工具接入协议，让工具提供方和模型使用方解耦。发布时自带 6 个官方 server（Google Drive、Slack、GitHub、Git、Postgres、Puppeteer）。现在社区建了<strong>数千个</strong>。</li><li><strong>它往上下文里塞了多少 token</strong>：<strong>MCP 本身不产生额外的协议开销——它的开销就是上面那张表</strong>。它的作用是让你<strong>更容易接入更多工具</strong>，而每一个接进来的工具都在往上下文里塞 schema。<strong>MCP 的便利性直接转化成了上下文压力，这是它最需要被理解的性质。</strong></li><li><strong>没有它会坏在哪</strong>：每个工具都要为每个模型单独写一遍适配。MCP 解决的是 M×N 问题。</li><li><strong>⚠️ 它同时制造了一个新问题</strong>：接入变简单之后，「装十个 server」的成本感知消失了，但 55K token 的账单还在。</li></ul><h3 id="工具搜索-把固定成本变成按需成本" tabindex="-1">工具搜索：把固定成本变成按需成本 <a class="header-anchor" href="#工具搜索-把固定成本变成按需成本" aria-label="Permalink to &quot;工具搜索：把固定成本变成按需成本&quot;">​</a></h3><ul><li><strong>是什么</strong>：不把全部工具定义塞进上下文，只塞一个「搜索工具的工具」，模型需要时再检索出 3~5 个具体工具。</li><li><strong>数字</strong>（全部第一方）： <ul><li>传统方式 50+ 个 MCP 工具 ≈ <strong>72,000 token</strong>；工具搜索方式前置加载 ≈ <strong>500 token</strong>。</li><li>定义负载降低 <strong>超过 85%</strong>：<strong>77,000 → 8,700 token，保住 95% 的上下文窗口</strong>。</li><li><strong>准确率同时上升</strong>：Opus 4 从 <strong>49% → 74%</strong>；Opus 4.5 从 <strong>79.5% → 88.1%</strong>。</li><li>官方给的切换阈值：<strong>≥10 个工具</strong>、或定义 <strong>&gt;10k token</strong>、或在做 MCP 聚合（200+ 工具）时该换；<strong>&lt;10 个工具且定义总量 &lt;100 token</strong> 时用标准方式就行。</li><li>硬限制：单请求最多 <strong>10,000 个延迟加载工具</strong>，搜索默认返回 <strong>5</strong> 个。</li></ul></li><li><strong>没有它会坏在哪</strong>：见上面那个 30~50 的悬崖。<strong>工具搜索本质上是在给模型做<a href="#_2-循环体-工具调用与-rag">检索</a>——只不过检索的对象是工具而不是文档。</strong></li></ul><h3 id="程序化工具调用-让工具结果不进上下文" tabindex="-1">程序化工具调用：让工具结果不进上下文 <a class="header-anchor" href="#程序化工具调用-让工具结果不进上下文" aria-label="Permalink to &quot;程序化工具调用：让工具结果不进上下文&quot;">​</a></h3><ul><li><strong>是什么</strong>：模型不再逐个调用工具、逐个接收结果，而是<strong>写一段代码</strong>，在沙箱里把多个工具串起来跑完，只把最终结果返回上下文。</li><li><strong>数字</strong>：复杂研究任务平均用量 <strong>43,588 → 27,297 token（降 37%）</strong>；准确率同步上升（内部知识检索 25.6% → 28.5%，GAIA 46.5% → 51.2%，复杂参数处理 72% → 90%）。 Anthropic 那篇《Code execution with MCP》给的场景化例子更夸张：<strong>150,000 → 2,000 token，省 98.7%</strong>。典型手法是「一万行的表格，agent 只看到五行」。</li><li><strong>没有它会坏在哪</strong>：中间结果全都要过一遍上下文。取一万行数据做个求和，那一万行就永久占据你的 <code>ctx</code>——而且后面每一轮都要重读一次。</li><li><strong>⚠️ 注意那个 98.7% 的性质</strong>：它是博客里的场景示例，不是 benchmark。同一篇里更硬的数字是 77K→8.7K 和那两组准确率提升，引用时优先用那几个。</li></ul><hr><h2 id="_2-循环体-工具调用与-rag" tabindex="-1">2. 循环体：工具调用与 RAG <a class="header-anchor" href="#_2-循环体-工具调用与-rag" aria-label="Permalink to &quot;2. 循环体：工具调用与 RAG&quot;">​</a></h2><h3 id="rag-检索增强生成" tabindex="-1">RAG（检索增强生成） <a class="header-anchor" href="#rag-检索增强生成" aria-label="Permalink to &quot;RAG（检索增强生成）&quot;">​</a></h3><ul><li><p><strong>是什么</strong>：把外部文档切块、向量化、建索引；提问时检索最相关的 k 块，塞进上下文。<strong>它就是 <code>execute()</code> 的一个特例</strong>——只不过被单独起了个名字，因为它出现得最早、用得最多。</p></li><li><p><strong>它往上下文里塞了多少 token</strong>：Databricks 那份 13 个模型的长上下文 RAG 研究用的是<strong>块大小 512 token、步长 256</strong>，检索块数 k 测了 1 / 5 / 13 / 29 / 61 / 125 / ... / 381。<strong>k=13 就是约 6,600 token，k=61 是约 31,000。</strong></p></li><li><p><strong>嵌入模型的规格</strong>（决定索引大小和检索质量）：</p><table tabindex="0"><thead><tr><th>模型</th><th>维度</th><th>最大序列</th></tr></thead><tbody><tr><td>text-embedding-3-small</td><td>1536（可降到 256）</td><td>8,191</td></tr><tr><td>text-embedding-3-large</td><td><strong>3072</strong></td><td>8,191</td></tr><tr><td>bge-large-en-v1.5</td><td>1024</td><td>512</td></tr><tr><td>BGE-M3</td><td>1024</td><td><strong>8,192</strong></td></tr><tr><td>Qwen3-Embedding-8B</td><td><strong>4096</strong>（可降到 32）</td><td><strong>32k</strong></td></tr></tbody></table></li><li><p><strong>没有它会坏在哪</strong>：模型只能靠<a href="/blog/ai/llm-basics/glossary.html#_1-预训练-pretraining-——最贵的一步">预训练</a>里的知识回答，而那些知识有截止日期、且无法引用来源。</p></li></ul><h3 id="⚠️-rag-最重要的一个反直觉数字" tabindex="-1">⚠️ RAG 最重要的一个反直觉数字 <a class="header-anchor" href="#⚠️-rag-最重要的一个反直觉数字" aria-label="Permalink to &quot;⚠️ RAG 最重要的一个反直觉数字&quot;">​</a></h3><p>Databricks 那份研究测出：<strong>检索召回率随上下文增长持续上升，但生成质量不跟着涨。</strong></p><p>召回率：2k → 0.468，16k → 0.839，64k → 0.927，128k → 0.95。 而各模型开始退化的位置：Mixtral-8x7b 在 4k 之后，DBRX 在 8k，GPT-4-turbo 和 Claude-3-sonnet 在 16k，Llama-3.1-405b 在 32k。</p><p>SWE-bench 论文里有一个更干净的版本，同一篇论文的两张表：</p><table tabindex="0"><thead><tr><th>上下文预算</th><th>BM25 召回率</th><th>Claude 2 解决率</th></tr></thead><tbody><tr><td>13k</td><td>29.58%</td><td><strong>1.96%</strong></td></tr><tr><td>27k</td><td>44.41%</td><td>1.87%</td></tr><tr><td>50k</td><td><strong>51.06%</strong></td><td><strong>1.22%</strong></td></tr></tbody></table><p><strong>召回率涨了 73%，解决率掉了 38%。</strong> 论文自己的结论是「模型在最短的上下文窗口下表现最好」。</p><p><strong>「检索到了」和「用对了」是两件事，而且它们的曲线是反向的。</strong> 这是整篇文章最该记住的一个事实——它直接否定了「把更多相关内容塞进去总没坏处」这个默认假设。</p><h3 id="结构化输出-约束解码" tabindex="-1">结构化输出 / 约束解码 <a class="header-anchor" href="#结构化输出-约束解码" aria-label="Permalink to &quot;结构化输出 / 约束解码&quot;">​</a></h3><ul><li><strong>是什么</strong>：在<a href="/blog/ai/llm-basics/glossary.html#温度-top-p-top-k-采样">采样</a>那一步动手脚——按语法把不合法的 token 的 logits 直接置 <code>-inf</code>，保证输出一定是合法 JSON。<strong>它作用的位置正是 <a href="/blog/ai/llm-basics/glossary.html#_5-出口-从向量到-token">glossary §5</a> 那个采样旋钮。</strong></li><li><strong>数字</strong>（XGrammar 论文，H100 + Llama-3.1-8B）：<strong>每 token 掩码生成 &lt;40 微秒</strong>；TPOT 开销几乎为零（JSON Schema，batch 1：<strong>6.2 → 6.3 ms</strong>；batch 16：9.0 → 9.2 ms）。相比现有方案，CFG 场景下单 token 延迟最多降 <strong>100×</strong>，端到端服务最多快 <strong>80×</strong>。 关键机制数字：<strong>上下文相关的 token 只占极小比例——Llama-3.1 用 JSON 语法时是 128k 里的 1,134 个，不到 1%</strong>。所以 99% 以上的掩码可以预计算。</li><li><strong>没有它会坏在哪</strong>：模型有一定概率吐出不合法 JSON，你的 <code>execute()</code> 直接抛异常。在一个几十轮的循环里，单轮 99% 的成功率意味着整体成功率 <code>0.99^30 ≈ 74%</code>。<strong>约束解码把这个概率变成 100%，不是提高了一点。</strong></li></ul><hr><h2 id="_3-上下文工程-管理那个只增不减的数组" tabindex="-1">3. 上下文工程：管理那个只增不减的数组 <a class="header-anchor" href="#_3-上下文工程-管理那个只增不减的数组" aria-label="Permalink to &quot;3. 上下文工程：管理那个只增不减的数组&quot;">​</a></h2><blockquote><p><a href="#_0-骨架">§0</a> 那段代码里，<code>ctx += [...]</code> 出现了三次，没有一次 <code>ctx -= [...]</code>。这一节讲的就是怎么补上那个减号。</p></blockquote><h3 id="有效上下文-标称长度是营销数字" tabindex="-1">有效上下文：标称长度是营销数字 <a class="header-anchor" href="#有效上下文-标称长度是营销数字" aria-label="Permalink to &quot;有效上下文：标称长度是营销数字&quot;">​</a></h3><p><a href="/blog/ai/llm-basics/glossary.html#上下文窗口-context-window">glossary §6</a> 已经提过「标称长度、可服务长度、有效长度是三个不同的数」。这里给出具体的数。</p><p><strong>NoLiMa（2025）</strong> 的做法是让「针」和「问题」<strong>几乎没有字面重叠</strong>，逼模型做语义关联而不是字符串匹配。有效长度定义为「保持短上下文成绩 85% 以上的最长长度」：</p><table tabindex="0"><thead><tr><th>模型</th><th>标称</th><th><strong>有效</strong></th><th>短上下文基线</th><th>32K 时</th></tr></thead><tbody><tr><td>GPT-4.1</td><td>1M</td><td><strong>16K</strong></td><td>97.0</td><td>79.8</td></tr><tr><td>GPT-4o</td><td>128K</td><td><strong>8K</strong></td><td>99.3</td><td><strong>69.7</strong></td></tr><tr><td>Claude 3.5 Sonnet</td><td>200K</td><td><strong>4K</strong></td><td>87.6</td><td><strong>29.8</strong></td></tr><tr><td>Llama 3.3 70B</td><td>128K</td><td><strong>2K</strong></td><td>97.3</td><td><strong>42.7</strong></td></tr><tr><td>Gemini 1.5 Pro</td><td><strong>2M</strong></td><td><strong>2K</strong></td><td>92.6</td><td><strong>48.2</strong></td></tr><tr><td>GPT-4o mini</td><td>128K</td><td><strong>&lt;1K</strong></td><td>84.9</td><td><strong>13.7</strong></td></tr></tbody></table><p><strong>测的 13 个模型全部声称支持 ≥128K，其中 11 个在 32K 时已经跌破短上下文成绩的一半。</strong> GPT-4o 是 8K 对 128K，<strong>差 16 倍</strong>；Gemini 1.5 Pro 是 2K 对 2M，<strong>差 1000 倍</strong>。</p><h3 id="⚠️-但这个数字取决于你怎么测" tabindex="-1">⚠️ 但这个数字取决于你怎么测 <a class="header-anchor" href="#⚠️-但这个数字取决于你怎么测" aria-label="Permalink to &quot;⚠️ 但这个数字取决于你怎么测&quot;">​</a></h3><p>RULER benchmark 对同一个 Gemini 1.5 Pro 的判决是<strong>有效长度 &gt;128K，128K 时还有 94.4%</strong>。和 NoLiMa 的 2K 差了 64 倍。</p><p>这不是谁测错了。<strong>区别在于 RULER 保留了字面重叠，NoLiMa 剥掉了。</strong></p><p>所以正确的表述是：<strong>「有效上下文长度」不是模型的属性，是「模型 × 任务字面重叠度」的属性。</strong> 你的任务越接近关键词匹配，可用长度越长；越依赖语义关联，可用长度掉得越快。RAG 恰好是后者——你检索回来的文档，和用户的问题往往用的不是同一套词。</p><h3 id="context-rot-上下文腐烂" tabindex="-1">Context rot（上下文腐烂） <a class="header-anchor" href="#context-rot-上下文腐烂" aria-label="Permalink to &quot;Context rot（上下文腐烂）&quot;">​</a></h3><p>Chroma 2025 年那份报告测了 <strong>18 个模型、194,480 次调用</strong>，结论：</p><blockquote><p>随着「针」和问题的语义相似度下降，<strong>模型性能随输入长度增长的退化更严重</strong>。测的 18 个模型，在每一个长度增量上全部退化。</p></blockquote><p>还有一个模型家族之间的行为差异值得记：<strong>Claude 系幻觉率最低但倾向于弃权（不答）；GPT 系在有干扰项时幻觉率最高。</strong>（GPT-3.5 Turbo 因为 60.29% 的拒答率被排除出统计。）</p><h3 id="具体的减号怎么打" tabindex="-1">具体的减号怎么打 <a class="header-anchor" href="#具体的减号怎么打" aria-label="Permalink to &quot;具体的减号怎么打&quot;">​</a></h3><ul><li><strong>裁剪历史</strong>：SWE-agent 的做法很直接——<strong>最近 5 条之外的观察结果，每条压成一行</strong>；除第一条外的所有报错信息直接删掉。论文给的理由有两条：省出上下文换更多交互轮次，以及<strong>避免过时的文件内容误导模型</strong>。第二条更重要。</li><li><strong>子 agent</strong>：Anthropic 的做法是让子 agent 探索「数万 token 或更多」，只把 <strong>1,000~2,000 token 的压缩摘要</strong>返回主循环。</li><li><strong>只保留最近的</strong>：Claude Code 保留<strong>最近访问的 5 个文件</strong>，其余压缩。</li><li><strong>把中间结果挡在上下文外</strong>：就是 <a href="#程序化工具调用-让工具结果不进上下文">§1</a> 那个程序化工具调用。</li></ul><p><strong>这四条是同一个动作的四个变体：让进入 <code>ctx</code> 的东西，少于工具产出的东西。</strong></p><hr><h2 id="_4-账单-一次-agent-任务多少钱" tabindex="-1">4. 账单：一次 agent 任务多少钱 <a class="header-anchor" href="#_4-账单-一次-agent-任务多少钱" aria-label="Permalink to &quot;4. 账单：一次 agent 任务多少钱&quot;">​</a></h2><h3 id="swe-agent-的实测数据-论文-最可信的一组" tabindex="-1">SWE-agent 的实测数据（论文，最可信的一组） <a class="header-anchor" href="#swe-agent-的实测数据-论文-最可信的一组" aria-label="Permalink to &quot;SWE-agent 的实测数据（论文，最可信的一组）&quot;">​</a></h3><p>SWE-bench 是 12 个 Python 仓库的 2,294 个真实 issue（Lite 300 个 / Verified 500 个）。任务规模：issue 文本平均 <strong>195 词</strong>，仓库非测试文件平均 <strong>3,010 个 / 43.8 万行</strong>，而标准答案平均只改 <strong>32.8 行、1.7 个文件</strong>。</p><p><strong>大海捞针的比例：从 43.8 万行里找出要改的 32.8 行。</strong></p><table tabindex="0"><thead><tr><th>方案</th><th>解决率</th><th>每个已解决实例平均成本</th></tr></thead><tbody><tr><td>RAG + GPT-4 Turbo</td><td>1.31%</td><td>$0.13</td></tr><tr><td>RAG + Claude 3 Opus</td><td>3.79%</td><td>$0.25</td></tr><tr><td><strong>SWE-agent + GPT-4 Turbo</strong></td><td><strong>12.47%</strong></td><td><strong>$1.59</strong></td></tr><tr><td>SWE-agent + Claude 3 Opus</td><td>10.46%</td><td>$2.59</td></tr></tbody></table><p>论文自己的总结：agent 方案比 RAG <strong>贵 8~13 倍，但解决率高 6.7 倍</strong>。</p><p><strong>轮次</strong>：GPT-4 Turbo 跑完整 SWE-bench 平均 <strong>14.71 轮</strong>，中位数 12，75% 的轨迹在 18 轮内完成。单实例预算上限 <strong>$4.00</strong>，大约对应 30~40 轮。</p><h3 id="⚠️-最值得记住的一个模式-成功快-失败慢" tabindex="-1">⚠️ 最值得记住的一个模式：成功快，失败慢 <a class="header-anchor" href="#⚠️-最值得记住的一个模式-成功快-失败慢" aria-label="Permalink to &quot;⚠️ 最值得记住的一个模式：成功快，失败慢&quot;">​</a></h3><blockquote><p>成功的实例中位数是 <strong>$1.21 / 12 步</strong>；失败的平均是 <strong>$2.52 / 21 步</strong>。</p></blockquote><p><strong>Agent 不是「多跑几轮就能做出来」。跑得越久，越可能是在打转。</strong> 93.0% 的已解决实例在预算耗尽前就提交了，而全体只有 69.0%。</p><p>这个现象的机制在 <a href="/blog/ai/llm-basics/glossary.html#自回归生成-autoregressive-generation">glossary §6</a>：自回归的误差会自我放大。第 10 轮走错方向，后面 11 轮都在这个错误的条件下生成，而且模型<strong>会努力让这个错误显得自洽</strong>。它不会自己意识到该回头。</p><p><strong>工程含义很直接：轮次上限不是省钱手段，是质量手段。</strong> 该早停就早停。</p><h3 id="提示缓存-agent-循环的必需品-不是优化项" tabindex="-1">提示缓存：agent 循环的必需品，不是优化项 <a class="header-anchor" href="#提示缓存-agent-循环的必需品-不是优化项" aria-label="Permalink to &quot;提示缓存：agent 循环的必需品，不是优化项&quot;">​</a></h3><p><a href="#_0-骨架">§0</a> 那个循环里，每一轮都要<strong>重读整个 <code>ctx</code></strong>。第 20 轮时你在为前 19 轮的内容重复付第 20 次钱。</p><table tabindex="0"><thead><tr><th>厂商</th><th>缓存读取折扣</th><th>写入成本</th><th>TTL</th><th>最小可缓存长度</th></tr></thead><tbody><tr><td><strong>Anthropic</strong></td><td><strong>0.1×（省 90%）</strong></td><td>1.25×（5分钟）/ 2×（1小时）</td><td>5 分钟 / 1 小时</td><td>512~4,096 token（按模型）</td></tr><tr><td><strong>OpenAI</strong></td><td><strong>0.1×（省 90%）</strong></td><td>无额外费用</td><td>5~10 分钟，最长 1 小时；GPT-5.6+ 为 30 分钟</td><td>≥1,024 token，按 128 递增命中</td></tr><tr><td><strong>Google</strong></td><td>隐式缓存默认开启</td><td>—</td><td>—</td><td>2,048~4,096 token（按模型）</td></tr></tbody></table><p>以 Claude Opus 5 为例：输入 $5/MTok，缓存命中 <strong>$0.50/MTok</strong>。</p><p><strong>⚠️ 而这直接约束了你的上下文布局</strong>：缓存是<strong>前缀匹配</strong>的。系统提示和工具定义必须放在最前面且<strong>永不改动</strong>，否则整个缓存作废。Anthropic 的工具搜索之所以设计成「延迟加载的工具不进系统提示前缀、发现的工具以 <code>tool_reference</code> 块追加在后面」，就是为了这个——官方原话是「前缀没被动过，所以提示缓存得以保留」。相应地，<code>defer_loading: true</code> 的工具上不能加 <code>cache_control</code>（会返回 400）。</p><p><strong>上下文里的东西该放哪个位置，是一个成本问题，不只是一个逻辑问题。</strong></p><h3 id="_1m-上下文能用多少" tabindex="-1">1M 上下文能用多少 <a class="header-anchor" href="#_1m-上下文能用多少" aria-label="Permalink to &quot;1M 上下文能用多少&quot;">​</a></h3><p>Gemini 3.1 Pro 的第一方数据最能说明问题：同一个 MRCR v2（8 针）benchmark，<strong>128k 处 84.9%，1M 处 26.3%</strong>。<strong>同一个模型、同一个测试，长度拉到 1M 掉了 3.2 倍。</strong></p><hr><h2 id="_5-这一切的思想原型" tabindex="-1">5. 这一切的思想原型 <a class="header-anchor" href="#_5-这一切的思想原型" aria-label="Permalink to &quot;5. 这一切的思想原型&quot;">​</a></h2><p>上面全部内容——工具定义、检索、上下文管理、轮次控制——都是在给同一个循环做工程。而那个循环 2022 年就被写出来了：</p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki material-theme-palenight vp-code" tabindex="0"><code><span class="line"><span>Thought:  我需要知道 X，应该先查 Y</span></span>
<span class="line"><span>Action:   search[Y]</span></span>
<span class="line"><span>Observation: (真实结果返回)</span></span>
<span class="line"><span>Thought:  结果没说 X，再查 Z</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span>Action:   finish[答案]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>这是 <a href="/blog/ai/agent/yao-2023-react.html">ReAct</a>。它用 <strong>1~2 个 in-context 示例、不做任何训练</strong>，就在 ALFWorld 和 WebShop 上比需要大量训练的强化学习基线<strong>绝对成功率高 34% / 10%</strong>（摘要口径；ALFWorld 那个 34% 是 best-of-6 对 best-of-8，六次均值只有 57 而非 71，详见<a href="/blog/ai/agent/yao-2023-react.html#实验结果">笔记</a>）。</p><p>四年过去，<a href="#_0-骨架">§0</a> 那段代码和这个循环是同构的。变的是三件事：</p><ol><li><strong>Thought 不再需要提示</strong>。<a href="/blog/ai/llm-basics/glossary.html#_4-推理训练-rlvr-rl-with-verifiable-rewards">glossary §7④</a> 讲的 RLVR 把「一步步想」训进了权重——CoT 从提示技巧变成了模型的默认行为。</li><li><strong>Action 的空间从 3 个变成了数千个</strong>。ReAct 的 HotpotQA 只有 <code>search</code> / <code>lookup</code> / <code>finish</code>；MCP 生态现在有数千个 server。<strong>而这正是 <a href="#_1-开工前-工具定义的固定成本">§1</a> 那个 55K token 账单的来源。</strong></li><li><strong>Observation 成了主要的成本项和主要的失败源</strong>。ReAct 时代观察结果就是一小段维基摘要；现在它可能是一万行表格、一整个代码库的检索结果。</li></ol><p>ReAct 论文当年诚实地列出了两种失败模式：CoT 的病是幻觉，ReAct 的病是<strong>卡死、被检索绑架</strong>。</p><p>四年后 SWE-agent 的数据给了这个判断一个量化版本：<strong>失败的任务平均跑 21 步、花 $2.52，而成功的中位数是 12 步、$1.21。</strong></p><p>「被检索绑架」现在有了数字。</p><hr><h2 id="_6-一句话收尾" tabindex="-1">6. 一句话收尾 <a class="header-anchor" href="#_6-一句话收尾" aria-label="Permalink to &quot;6. 一句话收尾&quot;">​</a></h2><p>Agent 不是一个新架构。它是 <a href="/blog/ai/llm-basics/glossary.html#_0-骨架">glossary §0</a> 那 12 行外面套的一个 while 循环，加上一个只增不减的数组。</p><p>所有的工程都发生在那个数组上：<strong>什么进得去，什么该被挡在外面，什么该被删掉，以及在第几轮该承认这次不会成功了。</strong></p><p>58 个工具 55,000 token，标称 128K 的有效长度是 8K，失败的任务比成功的多跑 9 步。这三个数字就是这一层的全部工程约束。</p><hr><h2 id="附-本文的证据分级" tabindex="-1">附：本文的证据分级 <a class="header-anchor" href="#附-本文的证据分级" aria-label="Permalink to &quot;附：本文的证据分级&quot;">​</a></h2><ul><li><strong>可直接引用</strong>（第一方文档或同行评议论文）：§1 的 Anthropic token 表与工具搜索数据、§2 的 Databricks 与 SWE-bench 检索数据、§2 的 XGrammar、§3 的 NoLiMa / RULER / Chroma、§4 的 SWE-agent 与三家缓存定价、§4 的 Gemini MRCR。</li><li><strong>场景示例而非 benchmark</strong>：MCP 那个 150k→2k / 98.7%。同一来源里更硬的数字是 77K→8.7K 和两组准确率提升，优先用后者。</li><li><strong>未采用</strong>：OpenAI 侧没有公布对等的工具调用 token 开销表，本文未给 OpenAI 的具体开销数字；网上流传的第三方 MCP token 测量（67,300 token / 7 个 server 等）未经方法审计，本文未采用；「约束解码会让模型变笨」这个说法没有找到可验证的测量，未采用。</li></ul>`,103)])])}const b=n(r,[["render",e]]);export{h as __pageData,b as default};
